SELECT MIN(T1.CIP_PROGRAM_CODE), COUNT(T2.DEPARTMENT_CODE), T3.SIS_ADMIN_DEPARTMENT_NAME FROM SIS_COURSE_DESCRIPTION AS T1 INNER JOIN SIS_DEPARTMENT AS T2 ON T1.DEPARTMENT = T2.DEPARTMENT_CODE INNER JOIN SIS_ADMIN_DEPARTMENT AS T3 ON T2.DEPARTMENT_CODE = T3.SIS_ADMIN_DEPARTMENT_CODE WHERE T1.SCHOOL_NAME = 'Engineering' AND T2.IS_DEGREE_GRANTING = 'Y' AND UPPER(T3.SIS_ADMIN_DEPARTMENT_NAME) = 'MECHANICAL ENGINEERING' AND T1.DEPARTMENT = '2' GROUP BY T3.SIS_ADMIN_DEPARTMENT_NAME